files.content:
:root {
  --bg: #1e1e2f;
  --surface: #2a2a40;
  --card-back: #3b3b5c;
  --accent: #f0a500;
  --text: #eaeaea;
  --matched: #4caf50;
  --radius: 10px;
  --gap: 12px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  padding: 24px;
}

.game {
  width: 100%;
  max-width: 560px;
  background: var(--surface);
  border-radius: var(--radius);
  padding: 24px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
}

.game-header {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-bottom: 20px;
}

h1 {
  font-size: 1.5rem;
  text-align: center;
  color: var(--accent);
}

.status {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
}

.moves {
  font-size: 1.1rem;
  font-weight: 600;
}

.btn {
  background: var(--accent);
  color: #1e1e2f;
  border: none;
  border-radius: var(--radius);
  padding: 10px 20px;
  font-size: 1rem;
  font-weight: 700;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
}

.btn:hover {
  background: #ffc233;
}

.btn:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 2px;
}

.btn:active {
  transform: scale(0.96);
}

.win-message {
  text-align: center;
  font-size: 1.2rem;
  font-weight: 700;
  color: var(--matched);
  padding: 8px;
  border-radius: var(--radius);
  background: rgba(76, 175, 80, 0.15);
}

.board {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--gap);
}

.card {
  aspect-ratio: 1 / 1;
  border-radius: var(--radius);
  border: 2px solid transparent;
  background: var(--card-back);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: transform 0.15s, background 0.2s, border-color 0.2s;
  position: relative;
  padding: 0;
  font-size: 0;
}

.card::after {
  content: '?';
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--text);
  opacity: 0.6;
}

.card:hover:not(.matched):not(.flipped) {
  background: #4a4a70;
}

.card:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.card:active:not(.matched) {
  transform: scale(0.95);
}

.card.flipped,
.card.matched {
  background: var(--color);
  border-color: var(--text);
}

.card.flipped::after,
.card.matched::after {
  content: '';
}

.card.matched {
  border-color: var(--matched);
  cursor: default;
  opacity: 0.85;
}

@media (max-width: 400px) {
  :root {
    --gap: 8px;
  }
  body {
    padding: 12px;
  }
  .game {
    padding: 16px;
  }
  h1 {
    font-size: 1.25rem;
  }
}

(() => {
  const COLORS = [
    '#e74c3c', '#3498db', '#2ecc71', '#f1c40f',
    '#9b59b6', '#e67e22', '#1abc9c', '#e84393'
  ];

  const board = document.getElementById('board');
  const movesEl = document.getElementById('moves');
  const winMessage = document.getElementById('win-message');
  const newGameBtn = document.getElementById('new-game');

  let firstCard = null;
  let lockBoard = false;
  let moves = 0;
  let matchedPairs = 0;

  function shuffle(array) {
    for (let i = array.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [array[i], array[j]] = [array[j], array[i]];
    }
    return array;
  }

  function createCard(color, index) {
    const card = document.createElement('button');
    card.type = 'button';
    card.className = 'card';
    card.dataset.color = color;
    card.style.setProperty('--color', color);
    card.setAttribute('aria-label', `Card ${index + 1}, face down`);
    card.addEventListener('click', () => flipCard(card));
    return card;
  }

  function flipCard(card) {
    if (lockBoard || card.classList.contains('flipped') || card.classList.contains('matched')) {
      return;
    }

    card.classList.add('flipped');
    card.setAttribute('aria-label', `Card, color ${card.dataset.color}`);

    if (!firstCard) {
      firstCard = card;
      return;
    }

    moves++;
    movesEl.textContent = moves;

    if (firstCard.dataset.color === card.dataset.color) {
      firstCard.classList.add('matched');
      card.classList.add('matched');
      firstCard.setAttribute('aria-label', `Matched card, color ${card.dataset.color}`);
      card.setAttribute('aria-label', `Matched card, color ${card.dataset.color}`);
      firstCard = null;
      matchedPairs++;
      if (matchedPairs === COLORS.length) {
        winMessage.hidden = false;
      }
    } else {
      lockBoard = true;
      const a = firstCard;
      const b = card;
      firstCard = null;
      setTimeout(() => {
        a.classList.remove('flipped');
        b.classList.remove('flipped');
        a.setAttribute('aria-label', 'Card, face down');
        b.setAttribute('aria-label', 'Card, face down');
        lockBoard = false;
      }, 800);
    }
  }

  function initGame() {
    board.innerHTML = '';
    firstCard = null;
    lockBoard = false;
    moves = 0;
    matchedPairs = 0;
    movesEl.textContent = '0';
    winMessage.hidden = true;

    const deck = shuffle([...COLORS, ...COLORS]);
    deck.forEach((color, i) => {
      board.appendChild(createCard(color, i));
    });
  }

  newGameBtn.addEventListener('click', initGame);
  initGame();
})();
